export enum BlockType {
  START = "start",
  END = "end",
  END_BLOCK = "end_block",
  INPUT_NUMBER = "input_number",
  VARIABLE = "variable",
  ADD = "add",
  SUBTRACT = "subtract",
  MULTIPLY = "multiply",
  DIVIDE = "divide",
  MODULO = "modulo",
  OUTPUT = "output",
  IF = "if",
  LOOP = "loop",
}

export enum BlockCategory {
  CONTROL = "control",
  DATA = "data",
  OPERATIONS = "operations",
  OUTPUT = "output",
}

export interface BlockDefinition {
  type: BlockType;
  category: BlockCategory;
  label: string;
  icon: string;
  description: string;
  hasParams: boolean;
  paramType?: "text" | "number" | "variable";
  paramLabel?: string;
}

export interface PlacedBlock {
  id: string;
  type: BlockType;
  order: number;
  params?: {
    value?: string;
    variableName?: string;
    condition?: string;
    iterations?: number;
  };
}

